DROP TABLE IF EXISTS `job_point_notes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_point_notes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `job_id` bigint unsigned NOT NULL,
  `credit_point_definition_id` bigint unsigned NOT NULL,
  `observations` text,
  `confirmed_in_result` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `review_status` enum('PENDING','NEEDS_REVIEW','APPROVED') NOT NULL DEFAULT 'PENDING',
  `review_note` text,
  `reviewed_by` int DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_job_point_note` (`job_id`,`credit_point_definition_id`),
  KEY `credit_point_definition_id` (`credit_point_definition_id`),
  CONSTRAINT `job_point_notes_ibfk_1` FOREIGN KEY (`job_id`) REFERENCES `jobs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `job_point_notes_ibfk_2` FOREIGN KEY (`credit_point_definition_id`) REFERENCES `credit_point_definitions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13851 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

